-- PostgreSQL 16+ logical schema for the football leaderboard.
-- UUID values are generated by the application so this schema needs no extensions.

BEGIN;

CREATE TABLE data_source (
    code            text PRIMARY KEY,
    display_name    text NOT NULL,
    base_url        text,
    is_canonical    boolean NOT NULL DEFAULT false,
    created_at      timestamptz NOT NULL DEFAULT now()
);

INSERT INTO data_source (code, display_name, base_url, is_canonical)
VALUES ('apf', 'Asociación Paraguaya de Fútbol', 'https://www.apf.org.py', true);

-- Immutable source responses. payload is preferred while body_uri permits moving
-- large objects to immutable object storage. At least one must be present.
CREATE TABLE raw_snapshot (
    id                  uuid PRIMARY KEY,
    source_code         text NOT NULL REFERENCES data_source(code),
    endpoint_kind       text NOT NULL CHECK (endpoint_kind IN ('discovery', 'gameweek', 'match')),
    source_entity_id    text,
    source_url          text NOT NULL,
    fetched_at          timestamptz NOT NULL,
    payload_sha256      char(64) NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
    payload             jsonb,
    body_uri            text,
    http_etag           text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CHECK (payload IS NOT NULL OR body_uri IS NOT NULL),
    UNIQUE (source_code, endpoint_kind, source_entity_id, fetched_at, payload_sha256)
);

CREATE INDEX raw_snapshot_entity_time_idx
    ON raw_snapshot (source_code, endpoint_kind, source_entity_id, fetched_at DESC);
CREATE INDEX raw_snapshot_hash_idx ON raw_snapshot (payload_sha256);

CREATE TABLE competition (
    id              uuid PRIMARY KEY,
    name            text NOT NULL,
    country_code    char(2) NOT NULL DEFAULT 'PY',
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE edition (
    id              uuid PRIMARY KEY,
    competition_id  uuid NOT NULL REFERENCES competition(id),
    name            text NOT NULL,
    season_year     integer,
    starts_on       date,
    ends_on         date,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (competition_id, name),
    CHECK (starts_on IS NULL OR ends_on IS NULL OR starts_on <= ends_on)
);

-- APF's "round" is a competition phase. Product-facing "rounds" are gameweeks.
CREATE TABLE tournament_stage (
    id              uuid PRIMARY KEY,
    edition_id      uuid NOT NULL REFERENCES edition(id),
    name            text NOT NULL,
    stage_order     integer,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (edition_id, name),
    UNIQUE (id, edition_id)
);

CREATE TABLE gameweek (
    id              uuid PRIMARY KEY,
    edition_id      uuid NOT NULL REFERENCES edition(id),
    stage_id        uuid,
    number          integer NOT NULL CHECK (number > 0),
    name            text NOT NULL,
    starts_at       timestamptz,
    ends_at         timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (edition_id, number),
    UNIQUE (id, edition_id),
    FOREIGN KEY (stage_id, edition_id) REFERENCES tournament_stage(id, edition_id),
    CHECK (starts_at IS NULL OR ends_at IS NULL OR starts_at <= ends_at)
);

CREATE TABLE team (
    id              uuid PRIMARY KEY,
    name            text NOT NULL,
    short_name      text,
    acronym         text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE player (
    id              uuid PRIMARY KEY,
    display_name    text NOT NULL,
    given_name      text,
    family_name     text,
    date_of_birth   date,
    nationality_code char(2),
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);

-- Participants observed in this edition. APF does not expose a separate
-- tournament roster route, so player/team membership is backed by match data.
CREATE TABLE edition_team (
    edition_id      uuid NOT NULL REFERENCES edition(id),
    team_id         uuid NOT NULL REFERENCES team(id),
    last_snapshot_id uuid NOT NULL REFERENCES raw_snapshot(id),
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (edition_id, team_id)
);

CREATE TABLE player_edition_team (
    edition_id      uuid NOT NULL REFERENCES edition(id),
    player_id       uuid NOT NULL REFERENCES player(id),
    team_id         uuid NOT NULL REFERENCES team(id),
    evidence        jsonb NOT NULL DEFAULT '{}'::jsonb,
    first_seen_at   timestamptz NOT NULL,
    last_seen_at    timestamptz NOT NULL,
    last_snapshot_id uuid NOT NULL REFERENCES raw_snapshot(id),
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (edition_id, player_id, team_id),
    CHECK (jsonb_typeof(evidence) = 'object'),
    CHECK (first_seen_at <= last_seen_at)
);

CREATE INDEX player_edition_team_team_idx
    ON player_edition_team (edition_id, team_id, player_id);

CREATE TABLE venue (
    id              uuid PRIMARY KEY,
    name            text NOT NULL,
    city            text,
    timezone_name   text NOT NULL DEFAULT 'America/Asuncion',
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);

-- All provider IDs, including APF UUIDs, are aliases of internal UUIDs. The
-- application must verify that canonical_id exists in the table for entity_type.
CREATE TABLE source_entity (
    source_code     text NOT NULL REFERENCES data_source(code),
    entity_type     text NOT NULL CHECK (entity_type IN (
                        'competition', 'edition', 'stage', 'gameweek', 'match',
                        'team', 'player', 'venue', 'event', 'lineup',
                        'team_stat', 'player_stat'
                    )),
    source_id       text NOT NULL,
    canonical_id    uuid NOT NULL,
    source_name     text,
    metadata        jsonb NOT NULL DEFAULT '{}'::jsonb,
    first_seen_at   timestamptz NOT NULL,
    last_seen_at    timestamptz NOT NULL,
    PRIMARY KEY (source_code, entity_type, source_id),
    CHECK (first_seen_at <= last_seen_at),
    CHECK (jsonb_typeof(metadata) = 'object')
);

CREATE INDEX source_entity_canonical_idx
    ON source_entity (entity_type, canonical_id);

CREATE TABLE position_group (
    code            text PRIMARY KEY,
    display_name    text NOT NULL UNIQUE,
    sort_order      smallint NOT NULL UNIQUE
);

INSERT INTO position_group (code, display_name, sort_order) VALUES
    ('GK',  'Goalkeeper', 1),
    ('DEF', 'Defender',   2),
    ('MID', 'Midfielder', 3),
    ('FWD', 'Forward',    4);

-- An editorial/resolved edition-level position, used by the global leaderboard.
-- Null means unresolved; unresolved players remain in the unfiltered leaderboard.
CREATE TABLE player_edition_profile (
    edition_id          uuid NOT NULL REFERENCES edition(id),
    player_id           uuid NOT NULL REFERENCES player(id),
    primary_position    text REFERENCES position_group(code),
    resolution_method   text NOT NULL CHECK (resolution_method IN (
                            'official', 'lineup_minutes', 'manual', 'unresolved'
                        )),
    resolution_note     text,
    source_snapshot_id  uuid REFERENCES raw_snapshot(id),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (edition_id, player_id)
);

CREATE TABLE football_match (
    id                      uuid PRIMARY KEY,
    edition_id              uuid NOT NULL REFERENCES edition(id),
    gameweek_id             uuid,
    venue_id                uuid REFERENCES venue(id),
    kickoff_at              timestamptz,
    status                  text NOT NULL CHECK (status IN (
                                'scheduled', 'live', 'finished', 'postponed',
                                'cancelled', 'abandoned', 'unknown'
                            )),
    source_status           text,
    period                  text,
    home_team_id            uuid NOT NULL REFERENCES team(id),
    away_team_id            uuid NOT NULL REFERENCES team(id),
    home_score              integer,
    away_score              integer,
    home_score_half_time    integer,
    away_score_half_time    integer,
    home_score_extra_time   integer,
    away_score_extra_time   integer,
    home_score_penalty      integer,
    away_score_penalty      integer,
    attendance              integer,
    last_snapshot_id        uuid NOT NULL REFERENCES raw_snapshot(id),
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (gameweek_id, edition_id) REFERENCES gameweek(id, edition_id),
    CHECK (home_team_id <> away_team_id),
    CHECK (home_score IS NULL OR home_score >= 0),
    CHECK (away_score IS NULL OR away_score >= 0),
    CHECK (home_score_half_time IS NULL OR home_score_half_time >= 0),
    CHECK (away_score_half_time IS NULL OR away_score_half_time >= 0),
    CHECK (home_score_extra_time IS NULL OR home_score_extra_time >= 0),
    CHECK (away_score_extra_time IS NULL OR away_score_extra_time >= 0),
    CHECK (home_score_penalty IS NULL OR home_score_penalty >= 0),
    CHECK (away_score_penalty IS NULL OR away_score_penalty >= 0),
    CHECK (attendance IS NULL OR attendance >= 0)
);

CREATE INDEX football_match_gameweek_idx ON football_match (gameweek_id, kickoff_at);
CREATE INDEX football_match_status_kickoff_idx ON football_match (status, kickoff_at);

CREATE TABLE match_event (
    id                  uuid PRIMARY KEY,
    match_id            uuid NOT NULL REFERENCES football_match(id) ON DELETE CASCADE,
    event_order         integer NOT NULL CHECK (event_order >= 0),
    event_type          text NOT NULL,
    qualification_type text,
    team_id             uuid REFERENCES team(id),
    player_id           uuid REFERENCES player(id),
    related_player_id   uuid REFERENCES player(id),
    period              text,
    minute              integer CHECK (minute IS NULL OR minute >= 0),
    second              integer CHECK (second IS NULL OR second BETWEEN 0 AND 59),
    home_score          integer CHECK (home_score IS NULL OR home_score >= 0),
    away_score          integer CHECK (away_score IS NULL OR away_score >= 0),
    qualifiers          jsonb NOT NULL DEFAULT '{}'::jsonb,
    is_active           boolean NOT NULL DEFAULT true,
    last_snapshot_id    uuid NOT NULL REFERENCES raw_snapshot(id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (match_id, event_order),
    CHECK (jsonb_typeof(qualifiers) IN ('object', 'array'))
);

CREATE INDEX match_event_match_time_idx
    ON match_event (match_id, minute, second, event_order) WHERE is_active;

CREATE TABLE match_lineup (
    id                  uuid PRIMARY KEY,
    match_id            uuid NOT NULL REFERENCES football_match(id) ON DELETE CASCADE,
    player_id           uuid NOT NULL REFERENCES player(id),
    team_id             uuid NOT NULL REFERENCES team(id),
    squad_role          text NOT NULL CHECK (squad_role IN ('starter', 'substitute')),
    captain             boolean,
    shirt_number        integer CHECK (shirt_number IS NULL OR shirt_number BETWEEN 0 AND 999),
    formation_place     text,
    position_code       text REFERENCES position_group(code),
    last_snapshot_id    uuid NOT NULL REFERENCES raw_snapshot(id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (match_id, player_id)
);

CREATE INDEX match_lineup_team_idx ON match_lineup (match_id, team_id);

-- Canonical metrics remain nullable: NULL means APF did not publish the metric;
-- zero means it explicitly published zero. raw_stats retains every Opta metric.
CREATE TABLE player_match_stat (
    id                      uuid PRIMARY KEY,
    match_id                uuid NOT NULL REFERENCES football_match(id) ON DELETE CASCADE,
    player_id               uuid NOT NULL REFERENCES player(id),
    team_id                 uuid NOT NULL REFERENCES team(id),
    minutes                 integer,
    goals                   integer,
    assists                 integer,
    yellow_cards            integer,
    red_cards               integer,
    saves                   integer,
    saves_inside_box        integer,
    passes_completed        integer,
    passes_attempted        integer,
    shots                   integer,
    shots_on_target         integer,
    touches                 integer,
    duels_won               integer,
    tackles_won             integer,
    tackles_attempted       integer,
    interceptions           integer,
    clearances              integer,
    recoveries              integer,
    fouls_committed         integer,
    fouls_suffered          integer,
    dribbles_completed      integer,
    dribbles_attempted      integer,
    crosses_completed       integer,
    crosses_attempted       integer,
    long_balls_completed    integer,
    long_balls_attempted    integer,
    offsides                integer,
    dispossessed            integer,
    raw_stats               jsonb NOT NULL,
    last_snapshot_id        uuid NOT NULL REFERENCES raw_snapshot(id),
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    UNIQUE (match_id, player_id),
    CHECK (jsonb_typeof(raw_stats) = 'object'),
    CHECK (minutes IS NULL OR minutes >= 0)
);

CREATE INDEX player_match_stat_player_idx ON player_match_stat (player_id, match_id);

CREATE TABLE team_match_stat (
    id                  uuid PRIMARY KEY,
    match_id            uuid NOT NULL REFERENCES football_match(id) ON DELETE CASCADE,
    team_id             uuid NOT NULL REFERENCES team(id),
    raw_stats           jsonb NOT NULL,
    last_snapshot_id    uuid NOT NULL REFERENCES raw_snapshot(id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (match_id, team_id),
    CHECK (jsonb_typeof(raw_stats) = 'object')
);

-- A published scoring model is immutable. New formula changes create a version.
-- formula stores the later scoring specification without coupling ingestion to it.
CREATE TABLE scoring_model (
    id              uuid PRIMARY KEY,
    name            text NOT NULL,
    version         integer NOT NULL CHECK (version > 0),
    status          text NOT NULL CHECK (status IN ('draft', 'active', 'retired')),
    points_scale    integer NOT NULL DEFAULT 1000 CHECK (points_scale = 1000),
    formula         jsonb NOT NULL,
    published_at    timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    UNIQUE (name, version),
    CHECK (jsonb_typeof(formula) = 'object'),
    CHECK ((status = 'draft') = (published_at IS NULL))
);

-- Every calculation identifies both the exact input snapshot and formula version.
CREATE TABLE match_score_run (
    id                  uuid PRIMARY KEY,
    scoring_model_id    uuid NOT NULL REFERENCES scoring_model(id),
    match_id            uuid NOT NULL REFERENCES football_match(id),
    source_snapshot_id  uuid NOT NULL REFERENCES raw_snapshot(id),
    input_sha256        char(64) NOT NULL CHECK (input_sha256 ~ '^[0-9a-f]{64}$'),
    state               text NOT NULL CHECK (state IN ('calculated', 'published', 'superseded', 'failed')),
    is_current          boolean NOT NULL DEFAULT false,
    error_message       text,
    calculated_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (scoring_model_id, match_id, input_sha256),
    CHECK ((state = 'failed') = (error_message IS NOT NULL)),
    CHECK (NOT is_current OR state = 'published')
);

CREATE UNIQUE INDEX match_score_run_one_current_idx
    ON match_score_run (scoring_model_id, match_id) WHERE is_current;

-- Scores are integer millipoints. This is exact in PostgreSQL and Redis doubles.
CREATE TABLE player_match_score (
    score_run_id        uuid NOT NULL REFERENCES match_score_run(id) ON DELETE CASCADE,
    player_id           uuid NOT NULL REFERENCES player(id),
    team_id             uuid NOT NULL REFERENCES team(id),
    position_code       text REFERENCES position_group(code),
    minutes             integer CHECK (minutes IS NULL OR minutes >= 0),
    points_milli        bigint NOT NULL CHECK (abs(points_milli) <= 9000000000000000),
    breakdown           jsonb NOT NULL,
    PRIMARY KEY (score_run_id, player_id),
    CHECK (jsonb_typeof(breakdown) = 'object')
);

CREATE INDEX player_match_score_player_idx ON player_match_score (player_id, score_run_id);

-- Current, rebuildable projections from published match score runs.
CREATE TABLE player_gameweek_score (
    scoring_model_id    uuid NOT NULL REFERENCES scoring_model(id),
    gameweek_id         uuid NOT NULL REFERENCES gameweek(id),
    player_id           uuid NOT NULL REFERENCES player(id),
    position_code       text REFERENCES position_group(code),
    appearances         integer NOT NULL CHECK (appearances >= 0),
    minutes             integer NOT NULL CHECK (minutes >= 0),
    points_milli        bigint NOT NULL CHECK (abs(points_milli) <= 9000000000000000),
    breakdown           jsonb NOT NULL,
    aggregate_version   bigint NOT NULL CHECK (aggregate_version > 0),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (scoring_model_id, gameweek_id, player_id),
    CHECK (jsonb_typeof(breakdown) = 'object')
);

CREATE INDEX player_gameweek_leaderboard_idx
    ON player_gameweek_score (scoring_model_id, gameweek_id, position_code, points_milli DESC, player_id DESC);

CREATE TABLE player_edition_score (
    scoring_model_id    uuid NOT NULL REFERENCES scoring_model(id),
    edition_id          uuid NOT NULL REFERENCES edition(id),
    player_id           uuid NOT NULL REFERENCES player(id),
    position_code       text REFERENCES position_group(code),
    appearances         integer NOT NULL CHECK (appearances >= 0),
    minutes             integer NOT NULL CHECK (minutes >= 0),
    points_milli        bigint NOT NULL CHECK (abs(points_milli) <= 9000000000000000),
    breakdown           jsonb NOT NULL,
    aggregate_version   bigint NOT NULL CHECK (aggregate_version > 0),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (scoring_model_id, edition_id, player_id),
    CHECK (jsonb_typeof(breakdown) = 'object')
);

CREATE INDEX player_edition_leaderboard_idx
    ON player_edition_score (scoring_model_id, edition_id, position_code, points_milli DESC, player_id DESC);

CREATE TABLE team_of_week (
    id                  uuid PRIMARY KEY,
    scoring_model_id    uuid NOT NULL REFERENCES scoring_model(id),
    gameweek_id         uuid NOT NULL REFERENCES gameweek(id),
    version             integer NOT NULL CHECK (version > 0),
    formation           text NOT NULL,
    selection_policy    jsonb NOT NULL,
    state               text NOT NULL CHECK (state IN ('draft', 'published', 'superseded')),
    is_current          boolean NOT NULL DEFAULT false,
    generated_at        timestamptz NOT NULL DEFAULT now(),
    published_at        timestamptz,
    UNIQUE (scoring_model_id, gameweek_id, version),
    CHECK (jsonb_typeof(selection_policy) = 'object'),
    CHECK (NOT is_current OR state = 'published')
);

CREATE UNIQUE INDEX team_of_week_one_current_idx
    ON team_of_week (scoring_model_id, gameweek_id) WHERE is_current;

CREATE TABLE team_of_week_player (
    team_of_week_id     uuid NOT NULL REFERENCES team_of_week(id) ON DELETE CASCADE,
    slot_code           text NOT NULL,
    slot_order          smallint NOT NULL CHECK (slot_order > 0),
    position_code       text NOT NULL REFERENCES position_group(code),
    player_id           uuid NOT NULL REFERENCES player(id),
    team_id             uuid NOT NULL REFERENCES team(id),
    points_milli        bigint NOT NULL CHECK (abs(points_milli) <= 9000000000000000),
    PRIMARY KEY (team_of_week_id, slot_code),
    UNIQUE (team_of_week_id, slot_order),
    UNIQUE (team_of_week_id, player_id)
);

-- Authentication is independent of football identity. No requirement currently
-- awards points to application users; Redis members are player UUIDs.
CREATE TABLE app_user (
    id                  uuid PRIMARY KEY,
    email               text NOT NULL,
    password_hash       text NOT NULL,
    display_name        text NOT NULL,
    role                text NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
    status              text NOT NULL DEFAULT 'active' CHECK (status IN ('pending', 'active', 'disabled')),
    email_verified_at   timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX app_user_email_ci_idx ON app_user (lower(email));

-- Store only a cryptographic hash of the opaque session token.
CREATE TABLE user_session (
    id                  uuid PRIMARY KEY,
    user_id             uuid NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    token_hash          char(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    created_at          timestamptz NOT NULL DEFAULT now(),
    expires_at          timestamptz NOT NULL,
    revoked_at          timestamptz,
    last_seen_at        timestamptz,
    CHECK (created_at < expires_at),
    CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

CREATE INDEX user_session_user_active_idx ON user_session (user_id, expires_at)
    WHERE revoked_at IS NULL;

-- Written in the same transaction as aggregate tables, then consumed to Redis.
CREATE TABLE leaderboard_outbox (
    id                      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    aggregate_type          text NOT NULL CHECK (aggregate_type IN ('gameweek', 'edition')),
    aggregate_id            uuid NOT NULL,
    scoring_model_id        uuid NOT NULL REFERENCES scoring_model(id),
    player_id               uuid NOT NULL REFERENCES player(id),
    previous_position_code  text REFERENCES position_group(code),
    position_code           text REFERENCES position_group(code),
    operation               text NOT NULL CHECK (operation IN ('upsert', 'delete')),
    points_milli            bigint CHECK (points_milli IS NULL OR abs(points_milli) <= 9000000000000000),
    aggregate_version       bigint NOT NULL CHECK (aggregate_version > 0),
    created_at              timestamptz NOT NULL DEFAULT now(),
    processed_at            timestamptz,
    last_error              text,
    UNIQUE (aggregate_type, aggregate_id, scoring_model_id, player_id, aggregate_version),
    CHECK ((operation = 'upsert' AND points_milli IS NOT NULL) OR
           (operation = 'delete' AND points_milli IS NULL))
);

CREATE INDEX leaderboard_outbox_pending_idx ON leaderboard_outbox (id)
    WHERE processed_at IS NULL;

COMMIT;
